insert into public.products (id, name, brand, category_slug, price, original_price, stock, requires_prescription, description, ingredients, usage, storage, warning, emoji, tone, rating, reviews, sold, badges, created_at) values
  ('sanmol-500', 'Sanmol Paracetamol 500 mg', 'Sanmol', 'obat', 9500, 12000, 124, false, 'Tablet paracetamol untuk membantu meredakan demam dan rasa nyeri ringan seperti sakit kepala atau sakit gigi.', 'Paracetamol 500 mg', 'Dewasa: 1 tablet, 3–4 kali sehari sesudah makan. Maksimal 8 tablet per hari. Ikuti petunjuk kemasan atau anjuran tenaga kesehatan.', 'Simpan di tempat kering, suhu di bawah 30°C, jauh dari sinar matahari langsung.', 'Tidak untuk penderita gangguan hati berat. Hentikan penggunaan bila muncul reaksi alergi dan konsultasikan ke dokter.', '💊', 'bg-primary-soft', 4.8, 214, 1840, array['Terlaris']::text[], '2025-11-02'),
  ('bodrex-migra', 'Bodrex Migra', 'Bodrex', 'obat', 8500, null, 88, false, 'Kombinasi paracetamol dan kafein untuk membantu meredakan sakit kepala termasuk migrain ringan.', 'Paracetamol 500 mg, Kafein 50 mg', 'Dewasa: 1 tablet, 3 kali sehari. Jangan melebihi dosis yang dianjurkan pada kemasan.', 'Simpan pada suhu ruang, terlindung dari cahaya.', 'Tidak dianjurkan untuk anak di bawah 12 tahun tanpa konsultasi dokter.', '🧠', 'bg-blush/60', 4.6, 132, 920, null, '2025-09-14'),
  ('amoxicillin-500', 'Amoxicillin 500 mg', 'Neon Pharma Generik', 'obat', 32000, null, 46, true, 'Antibiotik golongan penisilin yang digunakan sesuai resep dokter untuk infeksi bakteri tertentu.', 'Amoxicillin trihydrate 500 mg', 'Gunakan sesuai resep dokter. Antibiotik harus dihabiskan meskipun gejala sudah membaik.', 'Simpan di suhu ruang, kering, dan tertutup rapat.', 'Wajib resep dokter. Hentikan penggunaan bila muncul ruam atau sesak napas dan segera cari bantuan medis.', '🧪', 'bg-sky/50', 4.7, 64, 410, array['Resep']::text[], '2025-08-21'),
  ('omeprazole-20', 'Omeprazole 20 mg', 'Neon Pharma Generik', 'obat', 45000, null, 34, true, 'Obat penghambat pompa proton untuk membantu mengatasi keluhan lambung sesuai resep dokter.', 'Omeprazole 20 mg', 'Diminum sesuai resep dokter, umumnya sebelum makan pagi.', 'Simpan di bawah 30°C dalam wadah tertutup.', 'Wajib resep dokter. Konsultasikan bila keluhan berlanjut lebih dari 2 minggu.', '🫄', 'bg-mint/50', 4.5, 41, 280, array['Resep']::text[], '2025-07-30'),
  ('cetirizine-10', 'Cetirizine 10 mg', 'Neon Pharma Generik', 'obat', 18500, null, 72, false, 'Antihistamin untuk membantu meredakan gejala alergi seperti bersin dan gatal pada kulit.', 'Cetirizine dihydrochloride 10 mg', 'Dewasa: 1 tablet sekali sehari, sebaiknya malam hari.', 'Simpan pada suhu ruang, terlindung dari kelembapan.', 'Dapat menyebabkan kantuk. Hindari mengemudi setelah meminumnya.', '🌾', 'bg-primary-soft', 4.6, 57, 330, null, '2025-10-08'),
  ('betadine-60', 'Betadine Antiseptik 60 ml', 'Betadine', 'obat', 29000, 34000, 61, false, 'Larutan antiseptik povidone iodine untuk membersihkan luka luar pada kulit.', 'Povidone iodine 10%', 'Oleskan pada area luka yang telah dibersihkan, 1–2 kali sehari.', 'Simpan pada suhu ruang, hindari sinar matahari langsung.', 'Hanya untuk pemakaian luar. Jangan digunakan pada luka bakar luas tanpa konsultasi.', '🩹', 'bg-blush/60', 4.9, 176, 1210, array['Diskon']::text[], '2025-06-18'),
  ('redoxon-c', 'Redoxon Vitamin C 1000 mg', 'Redoxon', 'vitamin', 38000, 45000, 96, false, 'Tablet effervescent vitamin C untuk membantu memenuhi kebutuhan vitamin C harian.', 'Vitamin C (Ascorbic acid) 1000 mg', 'Larutkan 1 tablet dalam 200 ml air, 1 kali sehari.', 'Simpan tabung tertutup rapat di tempat kering.', 'Tidak menggantikan makanan bergizi seimbang.', '🍊', 'bg-mint/60', 4.8, 203, 1530, array['Terlaris','Diskon']::text[], '2025-11-10'),
  ('blackmores-d3', 'Blackmores Vitamin D3 1000 IU', 'Blackmores', 'vitamin', 189000, null, 28, false, 'Suplemen vitamin D3 untuk membantu memelihara kesehatan tulang.', 'Cholecalciferol (Vitamin D3) 1000 IU', 'Dewasa: 1 kapsul sehari sesudah makan.', 'Simpan di bawah 30°C, jauh dari jangkauan anak-anak.', 'Konsultasikan penggunaan bila sedang mengonsumsi obat lain.', '☀️', 'bg-primary-light/40', 4.7, 88, 460, null, '2025-10-22'),
  ('sangobion', 'Sangobion Kapsul 30', 'Sangobion', 'vitamin', 82000, null, 44, false, 'Suplemen zat besi untuk membantu mencegah dan mengatasi anemia defisiensi besi.', 'Ferrous fumarate, asam folat, vitamin B12, vitamin C', 'Dewasa: 1 kapsul sehari sesudah makan.', 'Simpan pada suhu ruang, terlindung dari cahaya.', 'Dapat menyebabkan tinja berwarna gelap. Jauhkan dari jangkauan anak-anak.', '🩸', 'bg-blush/60', 4.6, 121, 780, null, '2025-05-19'),
  ('holisticare-c', 'Holisticare Ester C', 'Holisticare', 'vitamin', 56000, null, 53, false, 'Suplemen vitamin C non-asam yang lembut untuk lambung.', 'Ester-C (Calcium ascorbate) 500 mg', '1 tablet sehari sesudah makan.', 'Simpan di tempat kering pada suhu ruang.', 'Bukan untuk menggantikan pola makan sehat.', '🍋', 'bg-mint/50', 4.5, 74, 390, null, '2025-09-02'),
  ('ensure-vanilla', 'Ensure Vanilla 400 g', 'Ensure', 'vitamin', 152000, 175000, 22, false, 'Susu nutrisi lengkap dengan protein, vitamin, dan mineral untuk orang dewasa.', 'Protein susu, maltodekstrin, campuran vitamin & mineral', 'Larutkan 4 sendok takar dalam 200 ml air, 1–2 kali sehari.', 'Tutup rapat setelah dibuka, gunakan dalam 3 minggu.', 'Tidak untuk penderita alergi protein susu sapi.', '🥛', 'bg-sky/50', 4.7, 96, 520, array['Baru','Diskon']::text[], '2025-11-16'),
  ('dettol-250', 'Dettol Sabun Cair 250 ml', 'Dettol', 'perawatan-diri', 27000, null, 140, false, 'Sabun cair antibakteri untuk kebersihan tangan dan tubuh sehari-hari.', 'Chloroxylenol, surfaktan lembut', 'Gunakan secukupnya pada tangan atau tubuh, bilas dengan air bersih.', 'Simpan di suhu ruang, hindari sinar matahari langsung.', 'Hanya untuk pemakaian luar.', '🧼', 'bg-sky/60', 4.8, 240, 2100, null, '2025-04-11'),
  ('sensodyne-100', 'Sensodyne Sensitif 100 g', 'Sensodyne', 'perawatan-diri', 46000, null, 77, false, 'Pasta gigi untuk gigi sensitif dengan perlindungan rasa nyaman saat menyikat.', 'Potassium nitrate 5%, sodium fluoride', 'Sikat gigi 2 kali sehari selama 2 menit.', 'Simpan pada suhu ruang.', 'Hentikan penggunaan bila timbul iritasi pada mulut.', '🪥', 'bg-primary-soft', 4.7, 158, 980, null, '2025-08-05'),
  ('listerine-250', 'Listerine Cool Mint 250 ml', 'Listerine', 'perawatan-diri', 34000, null, 65, false, 'Obat kumur antiseptik untuk membantu menjaga kebersihan mulut.', 'Thymol, eucalyptol, menthol, methyl salicylate', 'Berkumur 20 ml selama 30 detik, 2 kali sehari setelah menyikat gigi.', 'Simpan di tempat sejuk, tutup rapat.', 'Tidak untuk anak di bawah 12 tahun. Jangan ditelan.', '🌿', 'bg-mint/50', 4.6, 112, 640, null, '2025-07-12'),
  ('head-shoulders-340', 'Head & Shoulders Shampoo 340 ml', 'Head & Shoulders', 'perawatan-diri', 52000, 61000, 58, false, 'Sampo anti-ketombe dengan formula lembut untuk kulit kepala.', 'Zinc pyrithione, surfaktan lembut', 'Pijat ke kulit kepala, bilas hingga bersih. Gunakan 2–3 kali seminggu.', 'Simpan pada suhu ruang.', 'Hindari kontak dengan mata.', '🫧', 'bg-sky/50', 4.5, 89, 470, null, '2025-06-28'),
  ('cetaphil-cleanser', 'Cetaphil Gentle Skin Cleanser 250 ml', 'Cetaphil', 'perawatan-kulit', 128000, null, 39, false, 'Pembersih wajah lembut tanpa busa untuk kulit sensitif.', 'Cetyl alcohol, propylene glycol, panthenol', 'Usapkan pada wajah lalu bilas atau bersihkan dengan kapas.', 'Simpan pada suhu ruang, hindari sinar matahari langsung.', 'Hentikan bila terjadi iritasi.', '🧴', 'bg-blush/60', 4.9, 187, 890, array['Terlaris']::text[], '2025-10-30'),
  ('wardah-uv-shield', 'Wardah UV Shield SPF 35', 'Wardah', 'perawatan-kulit', 49000, null, 84, false, 'Sunscreen ringan dengan SPF 35 PA+++ untuk perlindungan harian.', 'Ethylhexyl methoxycinnamate, titanium dioxide', 'Aplikasikan merata pada wajah 15 menit sebelum aktivitas luar ruang.', 'Simpan di tempat sejuk, jauh dari sinar matahari langsung.', 'Hanya untuk pemakaian luar. Hindari area mata.', '🌤️', 'bg-primary-soft', 4.7, 264, 1450, array['Baru']::text[], '2025-11-04'),
  ('nivea-moist-100', 'Nivea Moisturizing Cream 100 ml', 'Nivea', 'perawatan-kulit', 39500, null, 91, false, 'Krim pelembap untuk kulit kering dengan tekstur ringan.', 'Glycerin, panthenol, paraffinum liquidum', 'Oleskan pada kulit yang kering 1–2 kali sehari.', 'Simpan pada suhu ruang.', 'Hindari penggunaan pada kulit yang luka.', '💧', 'bg-sky/50', 4.6, 143, 870, null, '2025-05-06'),
  ('omron-thermo', 'Omron Digital Thermometer MC-246', 'Omron', 'alat-kesehatan', 149000, 175000, 18, false, 'Termometer digital dengan hasil pembacaan cepat dan layar yang mudah dibaca.', 'Tidak berlaku (alat kesehatan)', 'Letakkan di bawah lidah atau ketiak hingga terdengar bunyi tanda selesai.', 'Simpan di kotak pelindung, jauh dari benturan.', 'Bersihkan sensor dengan alkohol sebelum dan sesudah pemakaian.', '🌡️', 'bg-primary-light/40', 4.8, 76, 310, array['Diskon']::text[], '2025-09-25'),
  ('omron-tensimeter', 'Omron Tensimeter Digital HEM-7156', 'Omron', 'alat-kesehatan', 615000, null, 9, false, 'Alat pengukur tekanan darah lengan atas dengan manset nyaman.', 'Tidak berlaku (alat kesehatan)', 'Duduk tenang 5 menit, pasang manset, lalu mulai pengukuran sesuai buku panduan.', 'Simpan di tempat kering, jauh dari medan magnet kuat.', 'Hasil pengukuran bukan pengganti diagnosis tenaga kesehatan.', '🩺', 'bg-blush/60', 4.9, 54, 190, null, '2025-08-17'),
  ('masker-medis-50', 'Masker Medis 3 Ply (50 pcs)', 'Neon Care', 'alat-kesehatan', 35000, null, 210, false, 'Masker medis tiga lapis dengan earloop elastis untuk pemakaian harian.', 'Tidak berlaku (alat kesehatan)', 'Tutup hidung dan mulut, ganti masker bila lembap atau kotor.', 'Simpan dalam kemasan tertutup di tempat kering.', 'Masker sekali pakai, jangan digunakan ulang.', '😷', 'bg-sky/60', 4.6, 168, 1300, null, '2025-10-12'),
  ('nebulizer-nec101', 'Nebulizer Omron NE-C101', 'Omron', 'alat-kesehatan', 425000, null, 6, false, 'Nebulizer kompresor untuk terapi uap di rumah, mudah dibersihkan.', 'Tidak berlaku (alat kesehatan)', 'Gunakan sesuai petunjuk tenaga kesehatan dan buku panduan alat.', 'Simpan di tempat kering, bersihkan setelah setiap pemakaian.', 'Gunakan obat nebulizer hanya sesuai anjuran dokter.', '🌬️', 'bg-mint/50', 4.7, 32, 95, null, '2025-07-23'),
  ('pampers-m', 'Pampers Premium Care M (40 pcs)', 'Pampers', 'ibu-bayi', 96000, 112000, 63, false, 'Popok bayi dengan permukaan lembut dan daya serap tinggi.', 'Tidak berlaku', 'Ganti popok secara berkala agar kulit bayi tetap kering.', 'Simpan di tempat kering, jauh dari kelembapan.', 'Hentikan pemakaian bila muncul iritasi pada kulit bayi.', '🍼', 'bg-mint/60', 4.8, 198, 1120, array['Diskon']::text[], '2025-11-08'),
  ('cussons-baby-powder', 'Cussons Baby Powder 150 g', 'Cussons', 'ibu-bayi', 24000, null, 110, false, 'Bedak bayi dengan aroma lembut untuk membantu menjaga kulit tetap kering.', 'Talc, zinc oxide, parfum', 'Taburkan tipis pada kulit bayi yang telah dikeringkan.', 'Simpan pada suhu ruang, tutup rapat.', 'Hindari area wajah untuk mencegah terhirup.', '👶', 'bg-blush/60', 4.5, 87, 560, null, '2025-06-09'),
  ('sgm-eksplor-1', 'SGM Eksplor 1+ 900 g', 'SGM', 'ibu-bayi', 118000, null, 37, false, 'Susu pertumbuhan untuk anak usia 1 tahun ke atas dengan nutrisi seimbang.', 'Susu bubuk skim, minyak nabati, vitamin & mineral', 'Larutkan sesuai petunjuk kemasan dengan air matang.', 'Tutup rapat setelah dibuka, gunakan dalam 4 minggu.', 'ASI adalah makanan terbaik untuk bayi. Konsultasikan dengan tenaga kesehatan.', '🥣', 'bg-primary-soft', 4.7, 132, 690, array['Baru']::text[], '2025-09-11'),
  ('tolak-angin', 'Tolak Angin Cair 12 sachet', 'Sido Muncul', 'obat', 36000, null, 105, false, 'Obat herbal untuk membantu meredakan gejala masuk angin seperti mual dan kembung.', 'Ekstrak jahe, madu, adas, mint', 'Dewasa: 1 sachet, 1–3 kali sehari.', 'Simpan di tempat sejuk dan kering.', 'Tidak dianjurkan untuk ibu hamil tanpa konsultasi.', '🍯', 'bg-mint/50', 4.4, 156, 990, null, '2025-04-27')
