-- Katalog awal NEON PHARMA (kategori + produk)
-- Jalankan setelah supabase/schema.sql

on conflict (slug) do update set name = excluded.name, short = excluded.short, emoji = excluded.emoji, tone = excluded.tone, blurb = excluded.blurb;

on conflict (id) do update set name = excluded.name, brand = excluded.brand, category_slug = excluded.category_slug, price = excluded.price, original_price = excluded.original_price, stock = excluded.stock, requires_prescription = excluded.requires_prescription, description = excluded.description, ingredients = excluded.ingredients, usage = excluded.usage, storage = excluded.storage, warning = excluded.warning, emoji = excluded.emoji, tone = excluded.tone, rating = excluded.rating, reviews = excluded.reviews, sold = excluded.sold, badges = excluded.badges;
